<template><AppLayout><div class="page-head"><div><h2>我的数字员工</h2><p class="muted">选择一个数字员工开始工作</p></div><el-button @click="refresh">刷新</el-button></div><el-skeleton v-if="loading" :rows="4" animated/><el-empty v-else-if="!store.employees.length" description="暂时没有可用的数字员工"/><div v-else class="employee-grid"><el-card v-for="employee in store.employees" :key="employee.id" class="employee-card"><div class="employee-icon">AI</div><h3>{{employee.name}}</h3><p>{{employee.description}}</p><el-tag :type="employee.available?'success':'info'">{{employee.available?'可用':'暂不可用'}}</el-tag><el-button type="primary" :disabled="!employee.available" @click="start(employee.id)">开始工作</el-button></el-card></div><section class="recent"><div class="section-title"><h3>最近会话</h3><el-button link @click="refresh">刷新</el-button></div><el-empty v-if="!store.sessions.length" description="还没有会话"/><el-table v-else :data="store.sessions" @row-click="open"><el-table-column prop="employeeName" label="数字员工"/><el-table-column label="最近活动"><template #default="scope">{{format(scope.row.lastActiveAt)}}</template></el-table-column><el-table-column prop="status" label="状态"/></el-table></section></AppLayout></template>
<script setup lang="ts">import { onMounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAppStore } from '../../stores/app'; import * as api from '../../api/app'; import AppLayout from '../../layouts/AppLayout.vue'; const store=useAppStore(); const router=useRouter(); const loading=ref(false); async function refresh(){loading.value=true;try{await Promise.all([store.loadEmployees(),store.loadSessions()])}finally{loading.value=false}} async function start(id:number){const s=await api.createSession(id);await router.push(`/app/sessions/${s.sessionId}`)} function open(row:any){router.push(`/app/sessions/${row.sessionId}`)} function format(v:string){return v?new Date(v).toLocaleString('zh-CN'):''} onMounted(refresh);</script>
